-- Migration 034: Personal-data anonymization and legal transaction retention.
-- Target: MariaDB 10.1.38. Apply manually after a backup.
-- Legal donor snapshots are private operational fields; no public donor schema
-- or public projection is created by this migration.

ALTER TABLE WEO_MEMBER
    ADD COLUMN USR_ANONYMIZED_AT DATETIME NULL,
    ADD COLUMN USR_PURGE_AT DATETIME NULL;

ALTER TABLE WEO_MEMBER
    ADD INDEX IDX_WM_PERSONAL_PURGE (USR_PURGE_AT);

ALTER TABLE WEO_ORDER
    ADD COLUMN O_ACCOUNT_USR_SEQ INT NULL,
    ADD COLUMN O_DONOR_NAME VARCHAR(100) NULL,
    ADD COLUMN O_DONOR_PHONE VARCHAR(11) CHARACTER SET ascii COLLATE ascii_bin NULL,
    ADD COLUMN O_DONOR_COHORT VARCHAR(20) NULL,
    ADD COLUMN O_DONOR_DEPARTMENT VARCHAR(100) NULL,
    ADD COLUMN O_LEGAL_RETENTION_UNTIL DATETIME NULL,
    ADD COLUMN O_ACCOUNT_UNLINKED_AT DATETIME NULL;

UPDATE WEO_ORDER
SET O_ACCOUNT_USR_SEQ = USR_SEQ
WHERE O_ACCOUNT_USR_SEQ IS NULL
  AND O_ACCOUNT_UNLINKED_AT IS NULL
  AND USR_SEQ > 0;

ALTER TABLE WEO_ORDER
    ADD INDEX IDX_WO_LEGAL_RETENTION (O_LEGAL_RETENTION_UNTIL, O_ACCOUNT_UNLINKED_AT),
    ADD INDEX IDX_WO_ACCOUNT_DATE (O_ACCOUNT_USR_SEQ, O_DONATION_DATE, O_SEQ);

ALTER TABLE ALUMNI_MESSAGE
    ADD COLUMN AM_SENDER_ACCOUNT_SEQ INT NULL,
    ADD COLUMN AM_RECVR_ACCOUNT_SEQ INT NULL,
    ADD COLUMN AM_SENDER_ANONYMIZED_YN ENUM('Y','N') NOT NULL DEFAULT 'N',
    ADD COLUMN AM_RECVR_ANONYMIZED_YN ENUM('Y','N') NOT NULL DEFAULT 'N';

UPDATE ALUMNI_MESSAGE
SET AM_SENDER_ACCOUNT_SEQ = CASE
        WHEN AM_SENDER_ACCOUNT_SEQ IS NULL AND AM_SENDER_ANONYMIZED_YN = 'N' THEN AM_SENDER_SEQ
        ELSE AM_SENDER_ACCOUNT_SEQ
    END,
    AM_RECVR_ACCOUNT_SEQ = CASE
        WHEN AM_RECVR_ACCOUNT_SEQ IS NULL AND AM_RECVR_ANONYMIZED_YN = 'N' THEN AM_RECVR_SEQ
        ELSE AM_RECVR_ACCOUNT_SEQ
    END
WHERE (AM_SENDER_ACCOUNT_SEQ IS NULL AND AM_SENDER_ANONYMIZED_YN = 'N')
   OR (AM_RECVR_ACCOUNT_SEQ IS NULL AND AM_RECVR_ANONYMIZED_YN = 'N');

ALTER TABLE ALUMNI_MESSAGE
    ADD INDEX IDX_AM_SENDER_ACCOUNT (AM_SENDER_ACCOUNT_SEQ, REG_DATE),
    ADD INDEX IDX_AM_RECVR_ACCOUNT (AM_RECVR_ACCOUNT_SEQ, REG_DATE);
